const cleaningLogId = $('Insert Cleaning Log').first().json.id;
const imageUrls = $('Webhook').first().json.body.image_urls;

if (!Array.isArray(imageUrls) || imageUrls.length === 0) {
  return [];
}

const mimeMap = { jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', webp: 'image/webp', heic: 'image/heic', heif: 'image/heif' };

return imageUrls.map(url => {
  const pathMatch = url.match(/\/object\/public\/evidence-photos\/(.+)/);
  const storage_path = pathMatch ? pathMatch[1] : url;
  const ext = url.split('.').pop()?.toLowerCase() ?? 'jpg';
  const file_type = mimeMap[ext] || 'image/jpeg';
  return {
    json: {
      cleaning_log_id: cleaningLogId,
      public_url: url,
      storage_path,
      file_type
    }
  };
});
